package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	line, _ := reader.ReadString('\n')
	line = strings.TrimRight(line, "\r\n")
	// ここで line の先頭の "Bearer " を取り除いてトークンだけを出力する
	_ = fmt.Sprint
}

package main

import (
	"fmt"
	"strconv"
)

func main() {
	var s string
	fmt.Scan(&s)
	// s を整数に変換し、成功なら整数を、失敗なら Bad request を出力する
	_ = strconv.Atoi
}

quiz.answer:
package main

import (
	"fmt"
	"strconv"
)

func main() {
	var s string
	fmt.Scan(&s)
	n, err := strconv.Atoi(s)
	if err != nil {
		fmt.Println("Bad request")
		return
	}
	fmt.Println(n)
}
